const base = { speed: 1 };
const fast = Object.create(base);
const racer = Object.create(fast);

fast.gear = 2;
base.gear = 20;
base.fuel = 30;

console.log(racer.speed, racer.gear, racer.fuel);

Object.setPrototypeOf(racer, base);

console.log(racer.speed, racer.gear, racer.fuel);
console.log(fast.gear, fast.fuel);
console.log(Object.getPrototypeOf(Object.getPrototypeOf(base)));
